USE rtools_marketplace;
CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(80) PRIMARY KEY, applied_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(64) PRIMARY KEY, name VARCHAR(80) NOT NULL, description VARCHAR(240), sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tags (id VARCHAR(64) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plugin_categories (plugin_id VARCHAR(128) NOT NULL,category_id VARCHAR(64) NOT NULL,PRIMARY KEY(plugin_id,category_id),FOREIGN KEY(plugin_id) REFERENCES plugins(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plugin_tags (plugin_id VARCHAR(128) NOT NULL,tag_id VARCHAR(64) NOT NULL,PRIMARY KEY(plugin_id,tag_id),FOREIGN KEY(plugin_id) REFERENCES plugins(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ratings (id CHAR(36) PRIMARY KEY,plugin_id VARCHAR(128) NOT NULL,user_key CHAR(64) NOT NULL,score TINYINT UNSIGNED NOT NULL,comment TEXT,status ENUM('visible','hidden') NOT NULL DEFAULT 'visible',created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uq_rating_user(plugin_id,user_key),FOREIGN KEY(plugin_id) REFERENCES plugins(id) ON DELETE CASCADE,CONSTRAINT chk_rating_score CHECK(score BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reports (id CHAR(36) PRIMARY KEY,plugin_id VARCHAR(128) NOT NULL,version VARCHAR(64),reporter_key CHAR(64) NOT NULL,reason VARCHAR(80) NOT NULL,details TEXT,status ENUM('open','resolved','dismissed') NOT NULL DEFAULT 'open',resolution_note TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),FOREIGN KEY(plugin_id) REFERENCES plugins(id) ON DELETE CASCADE,INDEX idx_reports_status(status)) ENGINE=InnoDB;
ALTER TABLE plugin_versions ADD COLUMN platforms_json JSON NULL, ADD COLUMN architectures_json JSON NULL, ADD COLUMN download_count BIGINT UNSIGNED NOT NULL DEFAULT 0;
INSERT IGNORE INTO categories(id,name,sort_order) VALUES ('productivity','效率工具',10),('developer','开发工具',20),('utilities','实用工具',30),('entertainment','娱乐',40);
INSERT IGNORE INTO schema_migrations(version) VALUES ('001_initial'),('002_market_features');
